use vstd::prelude::*;

verus! {
    fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8>
        requires
            a.len() == b.len() && a.len() > 0, // Preconditions: arrays must have equal length and be non-empty
        ensures
            result.len() == a.len() && 
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i] ^ b[i], // Postcondition: result[i] is the XOR of a[i] and b[i]
    {
        let n = a.len() as nat; // Get the length of the arrays
        let mut result: Vec<u8> = Vec::new(); // Initialize the result vector
        result.resize(n as usize, 0); // Resize the result vector to the same length as the input arrays

        let mut i: nat = 0; // Initialize the index
        while i < n // Loop through each index
            invariant
                0 <= i <= n && // Invariant: index is within bounds
                result.len() == n as usize, // Invariant: result has the correct length
                forall|j: nat| 0 <= j < i ==> result[j] == a[j] ^ b[j], // Invariant: all previous results are correct
            decreases n - i, // Decreases clause to ensure termination
        {
            result[i as usize] = a[i as usize] ^ b[i as usize]; // Perform the XOR operation
            i = i + 1; // Increment the index
        }
        result // Return the result vector
    }
}
